# Generated by test-lab — blind adversarial evaluation
# Tailored resume artifact gates (no PDF render, no network).
"""Behavioral gates for claim-bound variant markdown composition."""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from monitor_opportunities.resume_artifact import (
    ResumeArtifactError,
    approved_wordings,
    build_variant_markdown,
)

CLAIMS = Path("skills/monitor-opportunities/tests/fixtures/claims/approved-claims.json")


def _snapshot() -> dict:
    return json.loads(CLAIMS.read_text(encoding="utf-8"))


def _first_key() -> str:
    return _snapshot()["claims"][0]["claim_key"]


def test_variant_adds_only_approved_wordings() -> None:
    wordings = approved_wordings(_snapshot(), [_first_key()])
    base = "# Graham Anderson\n\nExperience...\n"
    variant = build_variant_markdown(base, {"title": "Role", "organization": "Org"}, wordings)
    added = [
        line for line in variant[len(base):].splitlines()
        if line.strip() and not line.startswith("#")
    ]
    approved = {row["text"] for row in wordings}
    assert added and all(line.lstrip("- ").strip() in approved for line in added)


def test_base_resume_content_is_preserved_verbatim() -> None:
    wordings = approved_wordings(_snapshot(), [_first_key()])
    base = "# Graham Anderson\n\nExperience...\n"
    variant = build_variant_markdown(base, {"title": "Role", "organization": "Org"}, wordings)
    assert variant.startswith(base.rstrip())


def test_unapproved_claim_fails_closed() -> None:
    with pytest.raises(ResumeArtifactError, match="UNAPPROVED_CLAIM"):
        approved_wordings(_snapshot(), ["claim:not-a-real-claim"])


def test_empty_claim_selection_fails_closed() -> None:
    with pytest.raises(ResumeArtifactError, match="NO_CLAIMS_SELECTED"):
        approved_wordings(_snapshot(), [])


def test_role_alignment_selects_only_existing_lines() -> None:
    from monitor_opportunities.resume_artifact import select_aligned_lines

    base = "\n".join([
        "# X",
        "- LLM agents, tool calling, RAG pipelines and evaluation harnesses",
        "- Knowledge graphs with ArangoDB and multi-hop traversal",
        "- Unrelated woodworking hobby line",
    ])
    posting = "We need RAG pipelines, LLM agents, tool calling and evaluation at scale"
    picked = select_aligned_lines(base, posting)
    assert picked and picked[0]["line"].startswith("- LLM agents")
    base_lines = set(base.splitlines())
    assert all(row["line"] in base_lines for row in picked)


def test_resume_skill_manifest_composition(tmp_path: Path) -> None:
    """Live composition of the /resume skill; no network, deterministic."""
    from monitor_opportunities.resume_artifact import compose_resume_variant_manifest

    snapshot = _snapshot()
    wordings = approved_wordings(snapshot, [_first_key()])
    base = tmp_path / "base.md"
    base.write_text("# Graham Anderson\n\nExperience...\n", encoding="utf-8")
    manifest = compose_resume_variant_manifest(
        claim_snapshot=snapshot,
        opportunity={"opportunity_id": "opp:test:1", "title": "Role", "organization": "Org"},
        wordings=wordings,
        base_path=base,
        out_dir=tmp_path,
    )
    assert manifest["schema"] == "resume.variant.v1"
    assert manifest["seam_validation"]["status"] == "PASS"
    assert [ref["claim_key"] for ref in manifest["claim_refs"]] == [_first_key()]
    assert Path(manifest["manifest_path"]).exists()


def test_resume_skill_manifest_rejects_evidence_free_claim(tmp_path: Path) -> None:
    from monitor_opportunities.resume_artifact import compose_resume_variant_manifest

    snapshot = _snapshot()
    wordings = approved_wordings(snapshot, [_first_key()])
    for claim in snapshot["claims"]:
        claim["evidence_refs"] = []
    base = tmp_path / "base.md"
    base.write_text("# Graham Anderson\n\nExperience...\n", encoding="utf-8")
    with pytest.raises(ResumeArtifactError, match="RESUME_SKILL_TAILOR_FAILED"):
        compose_resume_variant_manifest(
            claim_snapshot=snapshot,
            opportunity={"opportunity_id": "opp:test:2", "title": "Role", "organization": "Org"},
            wordings=wordings,
            base_path=base,
            out_dir=tmp_path,
        )


def test_competency_leads_come_from_the_registry(tmp_path: Path) -> None:
    """Live: the ranking is produced by /resume, not hardcoded here."""
    from monitor_opportunities.resume_artifact import rank_competencies

    posting = (
        "Build multi-agent LLM systems. You will own agent orchestration and tool "
        "calling, build evaluation harnesses and evals for agent behavior, and own "
        "observability, monitoring and guardrails for LLM pipelines."
    )
    leads = rank_competencies(posting)
    assert leads, "a posting naming evals, orchestration and observability ranked nothing"
    assert "evaluation-quality" in leads
    assert "observability-operations" in leads


def test_competency_ranking_is_never_a_gate() -> None:
    """An empty posting must degrade to no ordering, not an error."""
    from monitor_opportunities.resume_artifact import rank_competencies

    assert rank_competencies("") == []
    assert rank_competencies("   \n  ") == []


def test_variant_competency_section_names_only_registry_disciplines() -> None:
    """The added line orders disciplines; it must not mint a new claim."""
    from monitor_opportunities.resume_artifact import build_variant_markdown, rank_competencies

    snapshot = _snapshot()
    wordings = approved_wordings(snapshot, [_first_key()])
    posting = "agent orchestration, evals and observability for LLM pipelines"
    base = "# Graham Anderson\n\nExperience...\n"
    variant = build_variant_markdown(
        base, {"title": "Role", "organization": "Org"}, wordings, posting_text=posting
    )
    leads = rank_competencies(posting)
    if leads:
        assert "Competencies this role asks for" in variant
        for name in leads:
            assert name.replace("-", " ") in variant
